// The city's texts (city.js) in Bulgarian, as the sentences take them: server after "Сървърът …" ("Сървърът на град
// Brno не отговаря", so with "на"), dataName as the subject, capitalised ("… в момента не отговаря"), dataShort after
// "от" ("според данните от град Brno и OSM"), techMap as the subject of "Зарежда се …" (lower case, with the article).
const cap = (s) => s[0].toUpperCase() + s.slice(1);
const own = (name, of, map, data, parking, credit) => ({
  server: of, dataName: cap(map), dataShort: `${data} и OSM`, techMap: map,
  parkingSource: parking, rulesHead: `Ширини по Наръчника на IPR Praha (C.2), за ${name} ориентировъчно:`, credit,
});
